import { randomUUID } from "crypto";
import type Redis from "ioredis";

/**
 * Sliding-window-log rate limiter.
 *
 * For each client, `ratelimit:{clientId}` is a Redis SORTED SET (ZSET):
 * one member per in-window request, scored by the request's millisecond
 * timestamp. This makes the limiter exact, but memory and per-check CPU
 * both scale with the number of requests currently inside the window --
 * the hottest clients pay (and cost) the most.
 */
export class SlidingWindowLogLimiter {
  constructor(private readonly redis: Redis) {}

  /**
   * Returns true if `clientId` may make another request right now,
   * given `limit` requests per `windowMs` milliseconds.
   */
  async isAllowed(
    clientId: string,
    limit: number,
    windowMs: number,
  ): Promise<boolean> {
    const key = `ratelimit:${clientId}`;
    const now = Date.now();
    const windowStart = now - windowMs;

    // 1. Evict everything that fell out of the window.
    //    O(log N + M) where N = set size, M = evicted count.
    await this.redis.zremrangebyscore(key, 0, windowStart);

    // 2. Count what's left in the window. O(log N).
    const count = await this.redis.zcard(key);

    if (count >= limit) {
      return false;
    }

    // 3. Record this request as its own sorted-set entry.
    //    One ZADD member per request => O(N) memory per client.
    const requestId = randomUUID();
    await this.redis.zadd(key, now, requestId);
    await this.redis.pexpire(key, windowMs);

    return true;
  }
}
